#include <bits/stdc++.h>
#include <omp.h>
using namespace std; struct A{int A,B,dh,c,m; long long hb,lb,rb;};
vector<A> acts(long long P,long long Q,long long R){vector<pair<int,int>>ps;for(int i=0;i<=24;i++)for(int j=0;j<=24;j++)ps.push_back({40*i,40*j});const int ex[][2]={{6,236},{13,233},{67,237},{26,236},{94,234},{84,234},{3,223},{3,233},{74,234},{114,234},{4,234},{176,236},{115,235}};for(auto&p:ex)ps.push_back({4*p[0],4*p[1]});const int cut[][2]={{179,959},{613,953},{649,949},{539,959},{775,955},{885,945},{561,941},{419,959},{586,946},{215,955},{579,959},{70,910},{527,947},{497,957},{900,940},{291,951}};for(auto&p:cut)ps.push_back({p[0],p[1]});vector<A>as;for(auto [x,y]:ps){int dh=(9*x+11*y)/40,c=(11*x+9*y)/40,m=max(x,y);as.push_back({x,y,dh,c,m,(9LL*x*Q-10LL*P*m)*R,(-11LL*x*Q-10LL*P*m)*R,(9LL*y*Q-10LL*P*m)*R});}return as;}
int main(int argc,char**argv){if(argc!=4){cerr<<"usage r R k\n";return 2;}long long r=stoll(argv[1]),R=stoll(argv[2]);int target=stoi(argv[3]);const long long P=617,Q=253330;const int M=2600,MAXH=612;auto as=acts(P,Q,R);long long s=R-r;vector<long long>pr(M+1),ps(M+1),cr(M+1),cs(M+1);int stable=-1;for(int h=1;h<=MAXH;h++){
#pragma omp parallel for schedule(static)
for(int k=0;k<=M;k++){long long br=0,bs=0;for(auto&a:as){int kh=k+a.dh;long long HR=a.hb+(kh<=M?pr[kh]:0),HS=a.hb+(kh<=M?ps[kh]:0);long long LR,LS;if(k>=a.c){LR=a.lb+pr[k-a.c];LS=a.lb+ps[k-a.c];}else{int kl=a.c-k-1;long long xr=k*R+r,xs=k*R+s;LR=a.rb-40LL*xr*Q+ps[kl];LS=a.rb-40LL*xs*Q+pr[kl];}br=max(br,min(HR,LR));bs=max(bs,min(HS,LS));}cr[k]=br;cs[k]=bs;}if(cr==pr&&cs==ps){stable=h;break;}pr.swap(cr);ps.swap(cs);}cout<<pr[target]<<" "<<R<<" "<<stable<<"\n";}
